1	import { NextResponse } from "next/server";
2	import { Resolver } from "node:dns/promises";
3	import { jsonError, readField } from "@/lib/tools/api";
4	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
5	import { extractHost, isPlausibleHost, isBlockedIp } from "@/lib/tools/net-guard";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
12	 * node:dns. Public DNS only (no connections are made to the target), but we still
13	 * validate the hostname and cap output. Rate-limited per IP.
14	 */
15	
16	const TIMEOUT_MS = 5000;
17	const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
18	type RecordType = (typeof TYPES)[number];
19	
20	function withTimeout<T>(p: Promise<T>): Promise<T> {
21	  return Promise.race([
22	    p,
23	    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
24	  ]);
25	}
26	
27	export async function POST(req: Request) {
28	  const limited = toolRateLimitByIp(req, "dns", { max: 30, windowMs: 60_000 });
29	  if (limited) return limited;
30	
31	  const raw = await readField(req, "domain");
32	  const host = extractHost(raw);
33	  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
34	  if (host === "localhost") return jsonError("That host is not allowed.");
35	
36	  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });
37	
38	  async function resolveType(type: RecordType): Promise<string[]> {
39	    try {
40	      switch (type) {
41	        case "A":
42	          // Drop private/reserved answers so this public tool can't be used to
43	          // enumerate internal names the resolver happens to know (RFC1918,
44	          // 127/8, 169.254/16, etc.).
45	          return (await withTimeout(resolver.resolve4(host!))).filter((ip) => !isBlockedIp(ip));
46	        case "AAAA":
47	          return (await withTimeout(resolver.resolve6(host!))).filter((ip) => !isBlockedIp(ip));
48	        case "MX": {
49	          const mx = await withTimeout(resolver.resolveMx(host!));
50	          return mx
51	            .sort((a, b) => a.priority - b.priority)
52	            .map((r) => `${r.priority}\t${r.exchange}`);
53	        }
54	        case "TXT": {
55	          const txt = await withTimeout(resolver.resolveTxt(host!));
56	          return txt.map((chunks) => chunks.join(""));
57	        }
58	        case "NS":
59	          return await withTimeout(resolver.resolveNs(host!));
60	        case "CNAME":
61	          return await withTimeout(resolver.resolveCname(host!));
62	        case "SOA": {
63	          const soa = await withTimeout(resolver.resolveSoa(host!));
64	          return [
65	            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
66	          ];
67	        }
68	      }
69	    } catch {
70	      return [];
71	    }
72	  }
73	
74	  try {
75	    const settled = await Promise.all(
76	      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
77	    );
78	    const records: Record<string, string[]> = {};
79	    for (const [t, vals] of settled) records[t] = vals;
80	    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
81	    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
82	    return NextResponse.json({ ok: true, host, records });
83	  } catch {
84	    return jsonError("DNS lookup failed.", 502);
85	  }
86	}
