1	import { NextResponse } from "next/server";
2	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
3	
4	export const runtime = "nodejs";
5	export const dynamic = "force-dynamic";
6	
7	/**
8	 * Tiny latency probe for the browser Ping / Latency Test tool
9	 * (/tools/latency-test). It does nothing but return 200 as fast as possible with
10	 * a no-store header, so repeated client fetches measure round-trip time to the
11	 * Nxeon edge rather than any work this handler does.
12	 *
13	 * Rate-limited generously (a latency test fires ~10-20 quick requests); the cap
14	 * only exists so the endpoint can't be turned into a flood amplifier.
15	 */
16	export async function GET(req: Request) {
17	  const limited = toolRateLimitByIp(req, "ping", { max: 240, windowMs: 60_000 });
18	  if (limited) return limited;
19	  return new NextResponse(JSON.stringify({ ok: true, t: Date.now() }), {
20	    status: 200,
21	    headers: {
22	      "content-type": "application/json",
23	      "cache-control": "no-store, no-cache, must-revalidate",
24	    },
25	  });
26	}
27	
28	export function HEAD() {
29	  return new NextResponse(null, { status: 200, headers: { "cache-control": "no-store" } });
30	}
