1	import { NextResponse } from "next/server";
2	import net from "node:net";
3	import { resolveSrv } from "node:dns/promises";
4	import { jsonError } from "@/lib/tools/api";
5	import { toolRateLimitByIp, trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { checkRateLimit } from "@/lib/rate-limit";
7	import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";
8	
9	export const runtime = "nodejs";
10	export const dynamic = "force-dynamic";
11	
12	/**
13	 * Minecraft Server List Ping (Java Edition) over raw TCP.
14	 *
15	 * Implements the modern JSON handshake: we send a Handshake packet (next state =
16	 * status) followed by a Status Request, then read the length-prefixed JSON status
17	 * the server replies with — players online/max, MOTD, version, favicon presence —
18	 * and report the round-trip time as latency.
19	 *
20	 * SSRF-guarded like every other network tool: the (optionally SRV-resolved)
21	 * target is resolved to a public IP via `resolvePublicHost`, private/loopback/
22	 * reserved addresses are refused, and we connect to the vetted IP. Rate-limited
23	 * per IP and per target. Offline/timeout is a clean 200 with `online:false`, not
24	 * an error — an offline server is a normal, useful answer for this tool.
25	 */
26	
27	const DEFAULT_PORT = 25565;
28	const CONNECT_TIMEOUT_MS = 5000;
29	const READ_TIMEOUT_MS = 5000;
30	const PROTOCOL_VERSION = 47; // 1.8 — the most widely accepted handshake version.
31	const MAX_JSON_BYTES = 512 * 1024;
32	
33	/** Encode a non-negative integer as a Minecraft VarInt. */
34	function writeVarInt(value: number): Buffer {
35	  const bytes: number[] = [];
36	  let v = value >>> 0;
37	  for (;;) {
38	    if ((v & ~0x7f) === 0) {
39	      bytes.push(v);
40	      break;
41	    }
42	    bytes.push((v & 0x7f) | 0x80);
43	    v >>>= 7;
44	  }
45	  return Buffer.from(bytes);
46	}
47	
48	/** Read a VarInt from `buf` at `offset`. Returns null if more bytes are needed. */
49	function readVarInt(buf: Buffer, offset: number): { value: number; size: number } | null {
50	  let numRead = 0;
51	  let result = 0;
52	  let byte: number;
53	  do {
54	    if (offset + numRead >= buf.length) return null; // incomplete
55	    byte = buf[offset + numRead];
56	    result |= (byte & 0x7f) << (7 * numRead);
57	    numRead++;
58	    if (numRead > 5) return { value: result >>> 0, size: numRead }; // malformed, bail
59	  } while ((byte & 0x80) !== 0);
60	  return { value: result >>> 0, size: numRead };
61	}
62	
63	function encodeString(s: string): Buffer {
64	  const body = Buffer.from(s, "utf8");
65	  return Buffer.concat([writeVarInt(body.length), body]);
66	}
67	
68	/** Wrap a packet body (already including its packet-id VarInt) with a length prefix. */
69	function framePacket(body: Buffer): Buffer {
70	  return Buffer.concat([writeVarInt(body.length), body]);
71	}
72	
73	/** Pull readable plain text out of a MOTD, which may be a string or a chat component. */
74	function extractMotd(desc: unknown): string {
75	  if (typeof desc === "string") return desc;
76	  if (!desc || typeof desc !== "object") return "";
77	  const d = desc as Record<string, unknown>;
78	  let out = typeof d.text === "string" ? d.text : "";
79	  const extra = d.extra;
80	  if (Array.isArray(extra)) for (const part of extra) out += extractMotd(part);
81	  // Strip section-sign colour/format codes.
82	  return out.replace(/§[0-9a-fk-or]/gi, "").trim();
83	}
84	
85	type PingResult = {
86	  online: true;
87	  versionName: string | null;
88	  protocol: number | null;
89	  playersOnline: number | null;
90	  playersMax: number | null;
91	  sample: string[];
92	  motd: string;
93	  favicon: boolean;
94	  latencyMs: number;
95	};
96	
97	function pingServer(ip: string, port: number, hostname: string): Promise<PingResult> {
98	  return new Promise((resolve, reject) => {
99	    const socket = new net.Socket();
100	    let settled = false;
101	    let chunks: Buffer = Buffer.alloc(0);
102	    let started = 0;
103	
104	    const fail = (err: Error) => {
105	      if (settled) return;
106	      settled = true;
107	      socket.destroy();
108	      reject(err);
109	    };
110	
111	    socket.setTimeout(CONNECT_TIMEOUT_MS);
112	    socket.once("timeout", () => fail(new Error("timeout")));
113	    socket.once("error", (e) => fail(e));
114	
115	    socket.connect(port, ip, () => {
116	      socket.setTimeout(READ_TIMEOUT_MS);
117	      started = Date.now();
118	      // Handshake: id 0x00, protocol, server address, port (u16), next state = 1.
119	      const handshakeBody = Buffer.concat([
120	        writeVarInt(0x00),
121	        writeVarInt(PROTOCOL_VERSION),
122	        encodeString(hostname),
123	        Buffer.from([(port >> 8) & 0xff, port & 0xff]),
124	        writeVarInt(1),
125	      ]);
126	      // Status request: id 0x00, empty body.
127	      const statusRequest = framePacket(writeVarInt(0x00));
128	      socket.write(Buffer.concat([framePacket(handshakeBody), statusRequest]));
129	    });
130	
131	    socket.on("data", (data) => {
132	      chunks = Buffer.concat([chunks, data]);
133	      // Parse: [packet length VarInt][packet id VarInt = 0][json length VarInt][json].
134	      const lenHeader = readVarInt(chunks, 0);
135	      if (!lenHeader) return; // need more bytes for the frame length
136	      const packetLen = lenHeader.value;
137	      if (packetLen > MAX_JSON_BYTES) return fail(new Error("response too large"));
138	      const total = lenHeader.size + packetLen;
139	      if (chunks.length < total) return; // wait for the full frame
140	
141	      let cursor = lenHeader.size;
142	      const idHeader = readVarInt(chunks, cursor);
143	      if (!idHeader) return fail(new Error("malformed response"));
144	      cursor += idHeader.size;
145	      const jsonLen = readVarInt(chunks, cursor);
146	      if (!jsonLen) return fail(new Error("malformed response"));
147	      cursor += jsonLen.size;
148	      const jsonBuf = chunks.subarray(cursor, cursor + jsonLen.value);
149	
150	      let parsed: Record<string, unknown>;
151	      try {
152	        parsed = JSON.parse(jsonBuf.toString("utf8"));
153	      } catch {
154	        return fail(new Error("could not parse server status"));
155	      }
156	
157	      settled = true;
158	      const latencyMs = Date.now() - started;
159	      socket.destroy();
160	
161	      const version = (parsed.version ?? {}) as Record<string, unknown>;
162	      const players = (parsed.players ?? {}) as Record<string, unknown>;
163	      const sampleRaw = Array.isArray(players.sample) ? players.sample : [];
164	      const sample = sampleRaw
165	        .map((p) => (p && typeof p === "object" ? String((p as Record<string, unknown>).name ?? "") : ""))
166	        .filter(Boolean)
167	        .slice(0, 12);
168	
169	      resolve({
170	        online: true,
171	        versionName: typeof version.name === "string" ? version.name.replace(/§[0-9a-fk-or]/gi, "") : null,
172	        protocol: typeof version.protocol === "number" ? version.protocol : null,
173	        playersOnline: typeof players.online === "number" ? players.online : null,
174	        playersMax: typeof players.max === "number" ? players.max : null,
175	        sample,
176	        motd: extractMotd(parsed.description),
177	        favicon: typeof parsed.favicon === "string" && parsed.favicon.length > 0,
178	        latencyMs,
179	      });
180	    });
181	  });
182	}
183	
184	export async function POST(req: Request) {
185	  const limited = toolRateLimitByIp(req, "mc-status", { max: 20, windowMs: 60_000 });
186	  if (limited) return limited;
187	
188	  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
189	  const rawHost = extractHost(typeof body.host === "string" ? body.host : "");
190	  if (!rawHost) return jsonError("Enter a valid server address.");
191	
192	  const portGiven = body.port !== undefined && body.port !== null && String(body.port).trim() !== "";
193	  let port = portGiven ? Number(body.port) : DEFAULT_PORT;
194	  let targetHost = rawHost;
195	
196	  // Minecraft servers commonly advertise their real host:port via an SRV record
197	  // (_minecraft._tcp.<domain>). Only consult it when the visitor didn't pin a
198	  // port — an explicit port always wins.
199	  if (!portGiven && !net.isIP(rawHost)) {
200	    try {
201	      const srv = await resolveSrv(`_minecraft._tcp.${rawHost}`);
202	      if (srv.length > 0) {
203	        targetHost = srv[0].name.replace(/\.$/, "");
204	        port = srv[0].port;
205	      }
206	    } catch {
207	      /* no SRV record — use the host/port as given */
208	    }
209	  }
210	
211	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
212	    return jsonError("Port must be an integer between 1 and 65535.");
213	  }
214	
215	  try {
216	    const { host: resolved, addresses } = await resolvePublicHost(targetHost);
217	    const ip = addresses[0];
218	
219	    const sweep = checkRateLimit(`mcping:${trustedClientIp(req)}:${resolved}:${port}`, {
220	      max: 30,
221	      windowMs: 60_000,
222	    });
223	    if (!sweep.ok) return jsonError(`Too many checks against that server. Try again in ${sweep.retryAfterSec}s.`, 429);
224	
225	    try {
226	      const result = await pingServer(ip, port, resolved);
227	      return NextResponse.json({ ok: true, host: resolved, port, ...result });
228	    } catch {
229	      // Any protocol/connection failure = the server is unreachable for players.
230	      return NextResponse.json({ ok: true, host: resolved, port, online: false });
231	    }
232	  } catch (e) {
233	    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
234	    return jsonError("Status check failed.", 502);
235	  }
236	}
