1	import { NextResponse } from "next/server";
2	import net from "node:net";
3	import { jsonError } from "@/lib/tools/api";
4	import { toolRateLimitByIp, trustedClientIp } from "@/app/api/_lib/client-ip";
5	import { checkRateLimit } from "@/lib/rate-limit";
6	import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";
7	
8	export const runtime = "nodejs";
9	export const dynamic = "force-dynamic";
10	
11	/**
12	 * TCP port checker — opens a TCP connection to host:port and reports open/closed
13	 * plus connect latency. The host is SSRF-guarded (resolved to a public IP; private
14	 * / loopback / reserved targets are rejected) and we connect to the vetted IP,
15	 * never re-resolving. Port must be 1-65535. Timeout ≤5s, rate-limited per IP.
16	 */
17	
18	const TIMEOUT_MS = 5000;
19	
20	const COMMON: Record<number, string> = {
21	  20: "FTP-DATA", 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP", 53: "DNS",
22	  80: "HTTP", 110: "POP3", 143: "IMAP", 443: "HTTPS", 465: "SMTPS", 587: "SMTP",
23	  993: "IMAPS", 995: "POP3S", 3306: "MySQL", 3389: "RDP", 5432: "PostgreSQL",
24	  6379: "Redis", 8080: "HTTP-alt", 8443: "HTTPS-alt", 27017: "MongoDB",
25	};
26	
27	function tryConnect(ip: string, port: number): Promise<{ open: boolean; latencyMs: number }> {
28	  return new Promise((resolve) => {
29	    const started = Date.now();
30	    const socket = new net.Socket();
31	    let settled = false;
32	    const finish = (open: boolean) => {
33	      if (settled) return;
34	      settled = true;
35	      socket.destroy();
36	      resolve({ open, latencyMs: Date.now() - started });
37	    };
38	    socket.setTimeout(TIMEOUT_MS);
39	    socket.once("connect", () => finish(true));
40	    socket.once("timeout", () => finish(false));
41	    socket.once("error", () => finish(false));
42	    socket.connect(port, ip);
43	  });
44	}
45	
46	export async function POST(req: Request) {
47	  const limited = toolRateLimitByIp(req, "port", { max: 20, windowMs: 60_000 });
48	  if (limited) return limited;
49	
50	  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
51	  const host = extractHost(typeof body.host === "string" ? body.host : "");
52	  const port = Number(body.port);
53	
54	  if (!host) return jsonError("Enter a valid host.");
55	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
56	    return jsonError("Port must be an integer between 1 and 65535.");
57	  }
58	
59	  try {
60	    const { host: resolved, addresses } = await resolvePublicHost(host);
61	    const ip = addresses[0];
62	    // Extra per-target throttle so we can't be used to sweep one host's ports.
63	    const sweep = checkRateLimit(`portsweep:${trustedClientIp(req)}:${resolved}`, {
64	      max: 30,
65	      windowMs: 60_000,
66	    });
