68	
69	    const result = await tryConnect(ip, port);
70	    return NextResponse.json({
71	      ok: true,
72	      host: resolved,
73	      ip,
74	      port,
75	      service: COMMON[port] ?? null,
76	      open: result.open,
77	      latencyMs: result.open ? result.latencyMs : null,
78	    });
79	  } catch (e) {
80	    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
81	    return jsonError("Port check failed.", 502);
