11	/**
12	 * SSL/TLS certificate checker — TLS-connects to host:443 (SNI = host, connecting
13	 * to a vetted public IP) and reports issuer, subject, SAN, validity window, days
14	 * to expiry, and the chain. rejectUnauthorized is off so we can still inspect
15	 * expired / self-signed / mismatched certs and tell the user what's wrong.
16	 */
17	
18	const TIMEOUT_MS = 5000;
19	const DEFAULT_PORT = 443;
20	
21	function name(obj: unknown): string | null {
22	  if (!obj || typeof obj !== "object") return null;
23	  const rec = obj as Record<string, string>;
24	  return rec.CN || rec.O || (Object.values(rec).find((v) => typeof v === "string") ?? null);
25	}
26	
27	type ChainLink = { subject: string | null; issuer: string | null; validTo: string };
28	
29	function collectChain(cert: DetailedPeerCertificate): ChainLink[] {
30	  const out: ChainLink[] = [];
31	  const seen = new Set<string>();
32	  let cur: DetailedPeerCertificate | undefined = cert;
33	  while (cur && cur.fingerprint && !seen.has(cur.fingerprint)) {
34	    seen.add(cur.fingerprint);
35	    out.push({ subject: name(cur.subject), issuer: name(cur.issuer), validTo: cur.valid_to });
36	    if (cur.issuerCertificate && cur.issuerCertificate.fingerprint !== cur.fingerprint) {
37	      cur = cur.issuerCertificate;
38	    } else {
39	      break;
40	    }
41	    if (out.length >= 6) break;
42	  }
43	  return out;
44	}
