46	export async function POST(req: Request) {
47	  const limited = toolRateLimitByIp(req, "ssl", { max: 20, windowMs: 60_000 });
48	  if (limited) return limited;
49	
50	  const raw = await readField(req, "host");
51	  const host = extractHost(raw);
52	  if (!host) return jsonError("Enter a valid host (e.g. example.com).");
53	
54	  try {
55	    const { host: servername, addresses } = await resolvePublicHost(host);
56	    const ip = addresses[0];
57	
58	    const result = await new Promise<{ cert: DetailedPeerCertificate; authorized: boolean; error: string | null; protocol: string | null }>(
59	      (resolve, reject) => {
60	        const socket = tls.connect(
61	          {
62	            host: ip,
63	            port: DEFAULT_PORT,
64	            servername,
65	            rejectUnauthorized: false,
66	            timeout: TIMEOUT_MS,
67	          },
68	          () => {
69	            const cert = socket.getPeerCertificate(true);
70	            const protocol = socket.getProtocol();
71	            const authorized = socket.authorized;
72	            const error = socket.authorizationError ? String(socket.authorizationError) : null;
73	            socket.destroy();
74	            if (!cert || Object.keys(cert).length === 0) {
75	              reject(new Error("No certificate was presented."));
76	              return;
77	            }
78	            resolve({ cert, authorized, error, protocol });
79	          },
80	        );
81	        socket.setTimeout(TIMEOUT_MS);
82	        socket.once("timeout", () => {
83	          socket.destroy();
84	          reject(new Error("Connection timed out."));
85	        });
86	        socket.once("error", (e) => {
87	          socket.destroy();
88	          reject(e);
89	        });
90	      },
91	    );
92	
93	    const cert: PeerCertificate = result.cert;
94	    const validFrom = new Date(cert.valid_from);
95	    const validTo = new Date(cert.valid_to);
96	    const now = Date.now();
97	    const daysToExpiry = Math.floor((validTo.getTime() - now) / 86_400_000);
98	    const san = (cert.subjectaltname ?? "")
99	      .split(",")
100	      .map((s) => s.trim().replace(/^DNS:/, ""))
101	      .filter(Boolean)
102	      .slice(0, 30);
103	
104	    return NextResponse.json({
105	      ok: true,
106	      host: servername,
107	      subject: name(cert.subject),
108	      issuer: name(cert.issuer),
109	      altNames: san,
110	      validFrom: validFrom.toISOString(),
111	      validTo: validTo.toISOString(),
112	      daysToExpiry,
113	      expired: daysToExpiry < 0,
114	      valid: result.authorized,
115	      validationError: result.error,
116	      protocol: result.protocol,
117	      serialNumber: cert.serialNumber ?? null,
118	      chain: collectChain(result.cert),
119	    });
120	  } catch (e) {
121	    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
122	    const msg = e instanceof Error ? e.message : "SSL check failed.";
123	    return jsonError(`Could not complete TLS handshake: ${msg}`, 502);
124	  }
125	}
