1	import type { Client } from "ssh2";
2	import { exec, assertDomain, assert, shellQuote, SETUP_TIMEOUT_MS } from "./ssh-exec";
3	
4	/**
5	 * Shared HTTP verification for things we claim are "serving".
6	 *
7	 * Lifted verbatim out of worker/apps.ts, which is the file that got this right
8	 * first and is named in docs/QA-JOURNEY.md as the model. It lived there as two
9	 * private functions, so worker/websites.ts marked a site ACTIVE with the message
10	 * "Your nginx site is configured and serving" having made no request of any kind
11	 * (M7 #4) — and that unverified ACTIVE then gated the SSL flow, so certbot
12	 * HTTP-01 was offered for a vhost that might not answer at all.
13	 *
14	 * The rule this module exists to enforce: an install/config step that exited 0
15	 * is not evidence that anything is being served. Only a response is.
16	 */
17	
18	export type Probe = {
19	  /** Path on the app's own domain. */
20	  path: string;
21	  /** Accepted status codes (default: 200 only). */
22	  codes?: string[];
23	  /** Every pattern must be present in the body. */
24	  require: RegExp[];
25	  /** No pattern may be present (application-level error pages). */
26	  reject?: RegExp[];
27	  /** What passing this probe proves — quoted verbatim in failures. */
28	  proves: string;
29	};
30	
31	
32	/**
33	 * The remote shell for `httpProbe`, as a pure function.
34	 *
35	 * Split out from the SSH call so test/ssl-verify.test.ts can run `sh -n` and
36	 * `dash -n` over it. A quoting mistake in generated shell passes typecheck, lint
37	 * and build and then fails on a customer's live server — the same reason
38	 * test/migration-gate.test.ts parses `srcInventoryScript`.
39	 *
40	 * NOTE the `-k`: this probe answers "does this vhost serve this application",
41	 * and following an app's own http→https redirect to a self-signed or
42	 * not-yet-issued certificate must not fail that question. It therefore proves
43	 * NOTHING about TLS trust — use `tlsProbeCommand` for that, which deliberately
44	 * omits `-k`.
45	 */
46	export function httpProbeCommand(domain: string, path: string): string {
47	  assertDomain(domain);
48	  assert(/^\/[A-Za-z0-9._/-]*$/.test(path), `Unsupported probe path: ${path}`);
49	  return (
50	    `f=$(mktemp); c=$(curl -sS -k -L --max-redirs 5 --max-time 25 ` +
51	    `--resolve ${shellQuote(`${domain}:80:127.0.0.1`)} --resolve ${shellQuote(`${domain}:443:127.0.0.1`)} ` +
52	    `-o "$f" -w '%{http_code}' ${shellQuote(`http://${domain}${path}`)} 2>/dev/null); ` +
53	    `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 8192 "$f" 2>/dev/null; rm -f "$f"`
54	  );
55	}
56	
57	/**
58	 * Fetch one path on the app's own domain FROM INSIDE the VM, with the hostname
59	 * pinned to 127.0.0.1 (`curl --resolve`). That sends the real Host header, so it
60	 * genuinely tests "does this vhost serve this application" while remaining
61	 * correct before the customer's DNS has propagated. Mirrors the probe in
62	 * worker/migrate-real.ts, which exists because a port check proved only that
63	 * something was listening while sites returned 502s.
64	 */
65	export async function httpProbe(conn: Client, domain: string, path: string): Promise<{ code: string; body: string }> {
66	  const r = await exec(conn, httpProbeCommand(domain, path), SETUP_TIMEOUT_MS);
67	  const out = String(r.stdout ?? "");
68	  const m = /NXCODE:(\d{3})/.exec(out);
69	  const nl = out.indexOf("\n");
70	  // Keep newlines: stripping them would glue words together and make markers
71	  // unmatchable (see probeBody in worker/migrate-real.ts).
72	  // eslint-disable-next-line no-control-regex
73	  const body = (nl < 0 ? "" : out.slice(nl + 1)).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ");
74	  return { code: m ? m[1] : "000", body };
75	}
76	
77	/**
78	 * Run every probe for the app. Throws with the real HTTP result on the first
79	 * failure — an install that cannot be proved is a FAILED install, never a
80	 * quietly-downgraded one. Returns a one-line proof for the audit trail.
81	 */
82	export async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
83	  const proof: string[] = [];
84	  for (const p of probes) {
85	    const { code, body } = await httpProbe(conn, domain, p.path);
86	    if (!(p.codes ?? ["200"]).includes(code))
87	      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
88	    for (const re of p.reject ?? []) {
89	      const hit = re.exec(body);
90	      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);
91	    }
92	    for (const re of p.require) {
93	      if (!re.test(body))
94	        throw new Error(`verification failed: ${p.path} answered 200 but ${p.proves} could not be confirmed.`);
95	    }
96	    proof.push(`${p.path}=${code}`);
97	  }
98	  return `verified from the VM (${proof.join(" ")})`;
99	}
