101	// ---------------------------------------------------------------------------
102	// TLS: what a site actually serves on 443, and whether it is trusted
103	// ---------------------------------------------------------------------------
104	
105	/**
106	 * What `tlsProbeCommand` observed. Every field is something we SAW, never
107	 * something we inferred from an exit code.
108	 */
109	export type TlsProbe = {
110	  /** HTTP status from `https://<domain>/`. "000" = the request never completed. */
111	  httpsCode: string;
112	  /** curl's exit code for that request. 60 = the certificate was not trusted. */
113	  httpsRc: number;
114	  /** HTTP status from `http://<domain>/` WITHOUT following redirects. */
115	  httpCode: string;
116	  /** Where that plain-HTTP request would have been redirected to ("" = nowhere). */
117	  redirectTo: string;
118	  /** `systemctl is-active nginx` AFTER certbot rewrote the configuration. */
119	  nginxState: string;
120	  /** No END marker means the script did not finish and we know nothing. */
121	  complete: boolean;
122	};
123	
124	/** curl's "the peer certificate could not be verified" family. */
125	export const CURL_CERT_RCS = [60, 51, 91] as const;
126	
127	/**
128	 * The remote shell that answers "is HTTPS really working for this domain".
129	 *
130	 * THREE things it does that the code it replaces did not:
131	 *
132	 *  - NO `-k`. `certbot --nginx` exiting 0 is not evidence that a browser will
133	 *    accept what nginx now serves, and a probe that disables verification cannot
134	 *    tell the difference. curl exit 60 here IS the customer's browser warning.
135	 *  - NO `-L` on the plain-HTTP request. We claim "HTTP redirects to HTTPS", so
136	 *    the redirect itself is the thing under test; following it would hide its
137	 *    absence behind a 200 served over port 80.
138	 *  - It reads `systemctl is-active nginx` back. certbot --nginx REWRITES the
139	 *    customer's nginx configuration, and a dead nginx takes down every OTHER
140	 *    site on that box too.
141	 *
142	 * Pinned to 127.0.0.1 like `httpProbeCommand`, so it is correct before the
143	 * customer's DNS has propagated. Pure: covered by `sh -n`/`dash -n` in
144	 * test/ssl-verify.test.ts.
145	 */
146	export function tlsProbeCommand(domain: string): string {
147	  assertDomain(domain);
148	  const https = shellQuote(`https://${domain}/`);
149	  const http = shellQuote(`http://${domain}/`);
150	  const r443 = shellQuote(`${domain}:443:127.0.0.1`);
151	  const r80 = shellQuote(`${domain}:80:127.0.0.1`);
152	  return [
153	    `say() { printf 'NXTLS:%s\\n' "$1"; }`,
154	    // 1. The trust-checking request. No -k: a certificate a browser rejects must
155	    //    fail here, because that is exactly what the customer would see.
156	    `c=$(curl -sS -o /dev/null --max-time 20 --resolve ${r443} -w '%{http_code}' ${https} 2>/dev/null); rc=$?`,
157	    `say "HTTPS_CODE:${"$"}{c:-000}"`,
158	    `say "HTTPS_RC:$rc"`,
159	    // 2. The redirect claim, tested without following it.
160	    `h=$(curl -sS -o /dev/null --max-time 20 --resolve ${r80} -w '%{http_code} %{redirect_url}' ${http} 2>/dev/null)`,
161	    `say "HTTP:${"$"}{h:-000}"`,
162	    // 3. certbot just rewrote this file. Is the daemon still up?
163	    `n=$(systemctl is-active nginx 2>/dev/null); say "NGINX:${"$"}{n:-unknown}"`,
164	    `say "END"`,
165	  ].join("\n");
166	}
167	
168	/** Parse `tlsProbeCommand` output. Pure. */
169	export function parseTlsProbe(out: string): TlsProbe {
170	  const text = String(out ?? "");
171	  const one = (re: RegExp): string => re.exec(text)?.[1]?.trim() ?? "";
172	  const httpLine = one(/^NXTLS:HTTP:(.*)$/m);
173	  const [httpCode = "", redirectTo = ""] = httpLine.split(/\s+/);
174	  const rcRaw = one(/^NXTLS:HTTPS_RC:(-?\d+)$/m);
175	  return {
176	    httpsCode: one(/^NXTLS:HTTPS_CODE:(\d{3})$/m) || "000",
177	    httpsRc: rcRaw === "" ? -1 : Number(rcRaw),
178	    httpCode: /^\d{3}$/.test(httpCode) ? httpCode : "000",
179	    redirectTo,
180	    nginxState: one(/^NXTLS:NGINX:(.*)$/m) || "unknown",
181	    complete: /^NXTLS:END$/m.test(text),
182	  };
183	}
184	
185	/** Run `tlsProbeCommand` on the VM and parse it. */
186	export async function probeTls(conn: Client, domain: string): Promise<TlsProbe> {
187	  const r = await exec(conn, tlsProbeCommand(domain), SETUP_TIMEOUT_MS);
188	  return parseTlsProbe(String(r.stdout ?? ""));
189	}
