1	import { NextResponse } from "next/server";
2	import net from "node:net";
3	import { jsonError, readField } from "@/lib/tools/api";
4	import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";
5	import { extractHost, isPlausibleHost } from "@/lib/tools/net-guard";
6	
7	export const runtime = "nodejs";
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * WHOIS lookup — raw TCP (port 43) WHOIS client with IANA referral following.
12	 *
13	 * We query whois.iana.org first, read the "refer:" / "whois:" server for the TLD,
14	 * then re-query that authoritative server. No third-party API, no dependency.
15	 * The WHOIS servers we connect to are a fixed allowlist (IANA + the referred host,
16	 * itself validated as a public hostname), timeouts ≤5s, output capped.
17	 */
18	
19	const PORT = 43;
20	const TIMEOUT_MS = 5000;
21	const MAX_BYTES = 64 * 1024;
22	
23	/** One raw WHOIS query to `server:43` for `query`. Resolves with the text body. */
24	function whoisQuery(server: string, query: string): Promise<string> {
25	  return new Promise((resolve, reject) => {
26	    const chunks: Buffer[] = [];
27	    let size = 0;
28	    const socket = net.createConnection({ host: server, port: PORT });
29	    socket.setTimeout(TIMEOUT_MS);
30	
31	    const done = (err?: Error) => {
32	      socket.destroy();
33	      if (err) reject(err);
34	      else resolve(Buffer.concat(chunks).toString("utf8"));
35	    };
36	
37	    socket.on("connect", () => socket.write(`${query}\r\n`));
38	    socket.on("data", (d) => {
39	      size += d.length;
40	      if (size > MAX_BYTES) {
41	        chunks.push(d.subarray(0, Math.max(0, MAX_BYTES - (size - d.length))));
42	        done();
43	        return;
44	      }
45	      chunks.push(d);
46	    });
47	    socket.on("end", () => done());
48	    socket.on("timeout", () => done(new Error("WHOIS server timed out.")));
49	    socket.on("error", (e) => done(e));
50	  });
51	}
52	
53	/** Pull a referral WHOIS server (refer:/whois:) out of an IANA response. */
54	function parseReferral(text: string): string | null {
55	  const m = text.match(/^(?:refer|whois):\s*([a-z0-9.-]+)\s*$/im);
56	  return m ? m[1].toLowerCase() : null;
57	}
58	
59	/** Extract a few well-known fields for the summary card. */
60	function summarize(text: string) {
61	  const grab = (labels: string[]): string[] => {
62	    const out: string[] = [];
63	    for (const line of text.split(/\r?\n/)) {
64	      const m = line.match(/^\s*([^:]+):\s*(.+?)\s*$/);
65	      if (!m) continue;
66	      const key = m[1].trim().toLowerCase();
67	      if (labels.some((l) => key === l || key.startsWith(l))) out.push(m[2].trim());
68	    }
69	    return [...new Set(out)];
70	  };
71	  return {
72	    registrar: grab(["registrar", "sponsoring registrar"])[0] ?? null,
73	    created: grab(["creation date", "created", "registered on", "registration time"])[0] ?? null,
74	    updated: grab(["updated date", "last updated", "last modified"])[0] ?? null,
75	    expires: grab(["registry expiry date", "expiration date", "expiry date", "expires", "expire"])[0] ?? null,
76	    status: grab(["domain status", "status"]).slice(0, 6),
77	    nameservers: grab(["name server", "nserver", "nameserver"]).map((n) => n.toLowerCase()).slice(0, 8),
78	  };
79	}
80	
81	export async function POST(req: Request) {
82	  const limited = toolRateLimitByIp(req, "whois", { max: 15, windowMs: 60_000 });
83	  if (limited) return limited;
84	
85	  const raw = await readField(req, "domain");
86	  const host = extractHost(raw);
87	  if (!host || !isPlausibleHost(host) || net.isIP(host)) {
88	    return jsonError("Enter a valid domain name (e.g. example.com).");
89	  }
90	  if (host === "localhost" || !host.includes(".")) {
91	    return jsonError("Enter a fully-qualified domain name.");
92	  }
93	
94	  try {
95	    // 1) Ask IANA which server is authoritative for this TLD.
96	    const ianaText = await whoisQuery("whois.iana.org", host);
97	    const referral = parseReferral(ianaText);
98	
99	    let text = ianaText;
100	    let server = "whois.iana.org";
101	    // 2) Re-query the referred registry/registrar server if it's a valid public host.
102	    if (referral && isPlausibleHost(referral) && !net.isIP(referral) && referral !== "whois.iana.org") {
103	      try {
104	        const registryText = await whoisQuery(referral, host);
105	        if (registryText.trim().length > 0) {
106	          text = registryText;
107	          server = referral;
108	        }
109	      } catch {
110	        /* fall back to the IANA body */
111	      }
112	    }
113	
114	    if (!text.trim()) return jsonError("No WHOIS data returned for that domain.", 404);
115	
116	    return NextResponse.json({
117	      ok: true,
118	      host,
119	      server,
120	      summary: summarize(text),
121	      raw: text.slice(0, MAX_BYTES),
122	    });
123	  } catch (e) {
124	    const msg = e instanceof Error ? e.message : "WHOIS lookup failed.";
125	    return jsonError(msg, 502);
126	  }
127	}
