1	import { NextResponse } from "next/server";
2	import { reverse } from "node:dns/promises";
3	import net from "node:net";
4	import { trustedClientIp } from "@/app/api/_lib/client-ip";
5	
6	export const runtime = "nodejs";
7	export const dynamic = "force-dynamic";
8	
9	/**
10	 * "What's my IP" — echoes the caller's public IP plus a reverse-DNS (PTR)
11	 * lookup and a couple of request hints. No user input, so no SSRF surface.
12	 * Handy from a browser or `curl`.
13	 *
14	 * The address comes from `trustedClientIp` (proxy-attested), NOT the first hop
15	 * of `X-Forwarded-For`: nginx APPENDS to that header, so its first entry is
16	 * whatever the caller sent. Keying on it made this tool report an address the
17	 * caller chose — `curl -H 'X-Forwarded-For: 203.0.113.77' …/api/tools/my-ip`
18	 * answered `203.0.113.77`, which is worse than useless for a diagnostic tool.
19	 * `forwardedFor` below still echoes the raw header verbatim so a customer
20	 * debugging their own proxy chain can see it; that is their own input, not ours.
21	 */
22	
23	export async function GET(req: Request) {
24	  const ip = trustedClientIp(req);
25	  const kind = net.isIP(ip);
26	
27	  let ptr: string | null = null;
28	  if (kind !== 0) {
29	    try {
30	      const names = await Promise.race([
31	        reverse(ip),
32	        new Promise<string[]>((_, rej) => setTimeout(() => rej(new Error("timeout")), 3000)),
33	      ]);
34	      ptr = names[0] ?? null;
35	    } catch {
36	      ptr = null;
37	    }
38	  }
39	
40	  return NextResponse.json(
41	    {
42	      ok: true,
43	      ip,
44	      version: kind === 4 ? "IPv4" : kind === 6 ? "IPv6" : "unknown",
45	      reverseDns: ptr,
46	      userAgent: (req.headers.get("user-agent") ?? "").slice(0, 400) || null,
47	      forwardedFor: req.headers.get("x-forwarded-for") ?? null,
48	    },
49	    {
50	      // The response is a description of THIS caller. It carries no explicit
51	      // freshness information otherwise, which lets a shared proxy apply
52	      // heuristic caching (RFC 9111 §4.2.2) and hand one visitor's IP, PTR and
53	      // User-Agent to the next. Pin it to the caller.
54	      headers: { "Cache-Control": "private, no-store" },
55	    },
56	  );
57	}
