1	import { NextRequest, NextResponse } from "next/server";
2	import { currentUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { trustedClientIp } from "@/app/api/_lib/client-ip";
5	import { geoapifyConfigured, geoapifyAutocomplete } from "@/lib/geoapify";
6	
7	export const dynamic = "force-dynamic";
8	
9	/**
10	 * Server-side proxy for Geoapify's Autocomplete API — the GEOAPIFY_API_KEY never
11	 * reaches the client bundle. Serves two jobs from the domain-register wizard's
12	 * Contact step, both reading this same endpoint (see lib/geoapify.ts's doc
13	 * comment for why one proxy covers both):
14	 *   1. The debounced dropdown as the customer types their street address.
15	 *   2. A light confidence check on whatever they end up with (typed or picked)
16	 *      — advisory only, never a hard block.
17	 *
18	 * Signed-in only and rate-limited per user, the same shape as
19	 * app/api/domains/check/route.ts's registrar-lookup guard: this calls a metered
20	 * third-party API, and it is only ever used from an authenticated dashboard page.
21	 */
22	export async function GET(req: NextRequest) {
23	  const user = await currentUser();
24	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
25	
26	  if (!geoapifyConfigured()) {
27	    // The wizard only renders the autocomplete UI when the server component's
28	    // own `geoapifyConfigured()` read said yes, so reaching this with no key
29	    // configured means the key was pulled after the page loaded — degrade
30	    // quietly rather than error.
31	    return NextResponse.json({ configured: false, results: [] });
32	  }
33	
34	  const rl = checkRateLimit(`geoapify:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
35	  if (!rl.ok) {
36	    return NextResponse.json(
37	      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
38	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
39	    );
40	  }
41	
42	  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
43	  if (q.length < 3) return NextResponse.json({ configured: true, results: [] });
44	  const country = req.nextUrl.searchParams.get("country") ?? undefined;
45	
46	  try {
47	    const results = await geoapifyAutocomplete(q, country);
48	    return NextResponse.json({ configured: true, results });
49	  } catch (e) {
50	    // Best-effort: a Geoapify hiccup must never break the Contact step — the
51	    // field is a plain input underneath the dropdown either way.
52	    return NextResponse.json({
53	      configured: true,
54	      results: [],
55	      error: String(e instanceof Error ? e.message : e).slice(0, 200),
56	    });
57	  }
58	}
