1	import { NextRequest, NextResponse } from "next/server";
2	import { promises as fs } from "node:fs";
3	import { join } from "node:path";
4	import { randomBytes } from "node:crypto";
5	import { requireGrant } from "@/lib/staff-grants";
6	import { db } from "@/lib/db";
7	import { REDDIT_UPLOAD_DIR } from "@/lib/reddit-shared";
8	import { isAllowedImageMime, sniffImageMime } from "@/lib/chat-attachment";
9	
10	// Template post images are illustrative screenshots, not video — keep the cap
11	// tight like the other admin image uploads.
12	const MAX_IMAGE = 8 * 1024 * 1024;
13	
14	/**
15	 * Upload (or replace) a Reddit template's image. `?templateId=` in the
16	 * query. Mirrors app/api/board/attachments/route.ts's validation.
17	 *
18	 * Gated `requireGrant("redditTemplates")`, matching every export in
19	 * lib/actions-reddit-templates.ts (Phase 2) — this raw upload route sits
20	 * outside that action file so it was easy to miss when that migration ran.
21	 * It was still `requireAdmin()`-only, which would 403 a granted EMPLOYEE
22	 * trying to attach an image from the staff portal's Reddit page even though
23	 * every other Reddit action already worked for them.
24	 */
25	export async function POST(req: NextRequest) {
26	  try {
27	    await requireGrant("redditTemplates");
28	  } catch {
29	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
30	  }
31	  const templateId = req.nextUrl.searchParams.get("templateId") ?? "";
32	  const tpl = await db.redditTemplate.findUnique({ where: { id: templateId }, select: { id: true, imageStored: true } });
33	  if (!tpl) return NextResponse.json({ error: "Template not found" }, { status: 404 });
34	
35	  const form = await req.formData();
36	  const file = form.get("file");
37	  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
38	  if (file.size > MAX_IMAGE) {
39	    return NextResponse.json({ error: `Image too large (max ${Math.round(MAX_IMAGE / 1024 / 1024)} MB)` }, { status: 413 });
40	  }
41	
42	  const buf = Buffer.from(await file.arrayBuffer());
43	
44	  // Validate real bytes, not the client-declared type — same reasoning as the
45	  // board attachment route: never trust a claimed image/* MIME, and SVG is
46	  // rejected outright (no signature, stored-XSS risk if ever served inline).
47	  const sniffed = sniffImageMime(buf);
48	  const claimed = file.type || "application/octet-stream";
49	  if (!sniffed || claimed === "image/svg+xml" || !isAllowedImageMime(claimed)) {
50	    return NextResponse.json({ error: "Only PNG, JPEG, GIF, or WEBP images are allowed." }, { status: 400 });
51	  }
52	
53	  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
54	  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
55	  try {
56	    await fs.mkdir(REDDIT_UPLOAD_DIR, { recursive: true });
57	    await fs.writeFile(join(REDDIT_UPLOAD_DIR, storedName), buf);
58	  } catch (e) {
59	    console.error("[reddit] image write failed:", e);
60	    return NextResponse.json(
61	      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${REDDIT_UPLOAD_DIR} is writable by the web user.` },
62	      { status: 500 },
63	    );
64	  }
65	
66	  // Replacing an existing image: drop the old file once the new one is safely
67	  // written and the DB row is updated.
68	  const previousStored = tpl.imageStored;
69	  await db.redditTemplate.update({
70	    where: { id: templateId },
71	    data: { imageFilename: file.name.slice(0, 200), imageStored: storedName },
72	  });
73	  if (previousStored) {
74	    await fs.rm(join(REDDIT_UPLOAD_DIR, previousStored), { force: true }).catch(() => undefined);
75	  }
76	
77	  return NextResponse.json({ imageUrl: `/api/reddit/image/${templateId}`, imageFilename: file.name.slice(0, 200) });
78	}
