1	import { NextRequest, NextResponse } from "next/server";
2	import { createReadStream } from "node:fs";
3	import { promises as fs } from "node:fs";
4	import { join } from "node:path";
5	import { Readable } from "node:stream";
6	import { requireGrant } from "@/lib/staff-grants";
7	import { db } from "@/lib/db";
8	import { REDDIT_UPLOAD_DIR } from "@/lib/reddit-shared";
9	
10	/**
11	 * Serve a Reddit template's image, keyed by template id. Mirrors
12	 * app/api/board/attachments/[id]/route.ts's inline-serving headers.
13	 *
14	 * Gated `requireGrant("redditTemplates")` — same reasoning as the sibling
15	 * upload route in ../route.ts: left `requireAdmin()`-only, every template
16	 * thumbnail in RedditClient's grid would 403 for a granted EMPLOYEE viewing
17	 * /staff/reddit even though the page itself loads fine.
18	 */
19	export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
20	  try {
21	    await requireGrant("redditTemplates");
22	  } catch {
23	    return new NextResponse("Forbidden", { status: 403 });
24	  }
25	  const { id } = await params;
26	  const tpl = await db.redditTemplate.findUnique({ where: { id }, select: { imageStored: true, imageFilename: true } });
27	  if (!tpl?.imageStored) return new NextResponse("Not found", { status: 404 });
28	  const path = join(REDDIT_UPLOAD_DIR, tpl.imageStored);
29	  let size: number;
30	  try {
31	    size = (await fs.stat(path)).size;
32	  } catch {
33	    return new NextResponse("Missing", { status: 404 });
34	  }
35	
36	  const ext = tpl.imageStored.split(".").pop()?.toLowerCase() ?? "";
37	  const mime =
38	    ext === "png" ? "image/png" : ext === "gif" ? "image/gif" : ext === "webp" ? "image/webp" : "image/jpeg";
39	
40	  // Same defense-in-depth as the board attachment route: never let an inline
41	  // image execute as a document.
42	  const headers: Record<string, string> = {
43	    "Content-Type": mime,
44	    "Content-Disposition": "inline",
45	    "X-Content-Type-Options": "nosniff",
46	    "Content-Security-Policy": "default-src 'none'; sandbox",
47	    "Content-Length": String(size),
48	  };
49	
50	  const stream = createReadStream(path);
51	  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, { status: 200, headers });
52	}
