1	/**
2	 * Geoapify address autocomplete/geocoding — gated entirely on GEOAPIFY_API_KEY.
3	 *
4	 * No key exists in this environment yet (the owner will add the real value to
5	 * the live `.env` themselves). Every caller checks `geoapifyConfigured()` first
6	 * and degrades to the plain, always-worked text inputs when it's false — same
7	 * "don't claim a feature that isn't provisioned" rule the free-inbox plan
8	 * (`lib/domain-inbox-email.ts`) follows for the Email step. The API key itself
9	 * NEVER reaches the client — every call goes through this plain server module,
10	 * used only from the `/api/geoapify/autocomplete` route handler.
11	 */
12	
13	export function geoapifyConfigured(): boolean {
14	  return !!process.env.GEOAPIFY_API_KEY;
15	}
16	
17	export type GeoapifySuggestion = {
18	  formatted: string;
19	  address1: string;
20	  city: string;
21	  stateProvince: string;
22	  postalCode: string;
23	  /** ISO-3166 alpha-2, uppercased. */
24	  country: string;
25	  /** Geoapify's own match confidence, 0–1. Advisory only — never used to block
26	   *  a submission, only to flag a possibly-mistyped address (see the wizard's
27	   *  Street address field). */
28	  confidence: number;
29	};
30	
31	/**
32	 * Proxy Geoapify's Autocomplete API (also used, with a full free-text query, as
33	 * the "does this typed address resolve to anything real" confidence check —
34	 * Geoapify's autocomplete endpoint is built on the same geocoder and returns
35	 * the same `rank.confidence`/`rank.match_type` fields a dedicated geocode call
36	 * would, so one proxy route serves both jobs).
37	 *
38	 * Throws on a transport/HTTP failure — callers decide how to degrade (the
39	 * route handler turns a throw into an empty, non-fatal result; nothing here
40	 * silently invents a "no suggestions" answer that hides a real outage).
41	 */
42	export async function geoapifyAutocomplete(
43	  text: string,
44	  countryBias?: string,
45	): Promise<GeoapifySuggestion[]> {
46	  const apiKey = process.env.GEOAPIFY_API_KEY;
47	  if (!apiKey) throw new Error("Geoapify is not configured");
48	  const params = new URLSearchParams({
49	    text,
50	    format: "json",
51	    limit: "5",
52	    apiKey,
53	  });
54	  // Bias (not filter): a customer's mailing address can legitimately be in a
55	  // different country than the one their account/domain search defaults to, so
56	  // this must never EXCLUDE other countries' results, only prefer the hinted one.
57	  if (countryBias && /^[A-Za-z]{2}$/.test(countryBias)) {
58	    params.set("bias", `countrycode:${countryBias.toLowerCase()}`);
59	  }
60	  const res = await fetch(`https://api.geoapify.com/v1/geocode/autocomplete?${params.toString()}`, {
61	    signal: AbortSignal.timeout(8_000),
62	  });
63	  if (!res.ok) {
64	    const body = await res.text().catch(() => "");
65	    throw new Error(`Geoapify: HTTP ${res.status}${body ? ` — ${body.slice(0, 200)}` : ""}`);
66	  }
67	  const json = await res.json();
68	  const results: any[] = Array.isArray(json?.results) ? json.results : [];
69	  return results.map((r) => ({
70	    formatted: String(r.formatted ?? ""),
71	    address1: String(r.address_line1 ?? r.formatted ?? ""),
72	    city: String(r.city ?? r.county ?? ""),
73	    stateProvince: String(r.state ?? ""),
74	    postalCode: String(r.postcode ?? ""),
75	    country: String(r.country_code ?? "").toUpperCase(),
76	    confidence: typeof r.rank?.confidence === "number" ? r.rank.confidence : 0,
77	  }));
78	}
