204	/**
205	 * `Job.step` values written by worker/ssl.ts. Duplicated there (and in
206	 * lib/actions-ssl.ts) because neither can import the other; the strings are the
207	 * contract.
208	 */
209	export const STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
210	export const STEP_SANDBOX = "simulated (sandbox)";
211	
212	/** One SSL_ISSUE Job row, as the counter needs to see it. */
213	export type IssueJobRow = {
214	  domain: string;
215	  /** `Job.attempts` — the worker INCREMENTS this and re-runs the SAME row. */
216	  attempts: number;
217	  /** `Job.step` — only ever records the outcome of the LAST attempt. */
218	  step: string | null;
219	  createdAt: Date;
220	};
221	
222	export type IssueTally = {
223	  /** Executions of any kind, including ones that never reached the ACME server. */
224	  total: number;
225	  /** Executions that may have consumed a Let's Encrypt duplicate-certificate slot. */
226	  leRelevant: number;
227	  lastAt: Date;
228	};
229	
230	/**
231	 * Count issue attempts per hostname inside the rate-limit window.
232	 *
233	 * THE BUG THIS EXISTS TO FIX: the counter used to be `+1 per Job row`. But
234	 * worker/index.ts does not create a new row to retry — it flips the SAME row
235	 * back to QUEUED and increments `attempts` (`MAX_ATTEMPTS = 3`), and
236	 * `reapStuckJobs` does the same to any job that was RUNNING when the worker
237	 * restarted. A deploy restarts nxeon-worker, and `certbot certonly` takes tens
238	 * of seconds, so this is a live path, not a theoretical one.
239	 *
240	 * One row could therefore drive THREE real certbot invocations while the counter
241	 * scored it as one. With the cap set at 4 rows, a hostname could reach twelve
242	 * ACME requests in a week against Let's Encrypt's limit of 5 duplicate
243	 * certificates — the precise outcome the cap exists to prevent, and it costs the
244	 * customer HTTPS for a full week.
245	 *
246	 * So we count EXECUTIONS, not rows. And for a row with more than one execution
247	 * we count every one of them as rate-limit-relevant: `step` records only the
248	 * final attempt's outcome, so a row that reached ACME on attempt 1 and died in
249	 * pre-flight on attempt 2 reads as "never reached Let's Encrypt". When in doubt,
250	 * protect the limit — the same rule `attemptCountsAgainstLimit` already applies
251	 * to a null step.
252	 *
253	 * Pure: no database, no clock. Covered by test/ssl-verify.test.ts.
254	 */
255	export function tallyIssueAttempts(jobs: readonly IssueJobRow[]): Map<string, IssueTally> {
256	  const map = new Map<string, IssueTally>();
257	  for (const j of jobs) {
258	    if (!j.domain) continue; // pre-2026-07-26 rows carried only certId
259	    // `attempts` is incremented when a job is CLAIMED, so a queued-but-never-run
260	    // row reads 0. It is still an intent to contact Let's Encrypt, and treating
261	    // it as zero would let a burst of queued rows slip under the cap.
262	    const runs = Math.max(1, Number.isFinite(j.attempts) ? Math.trunc(j.attempts) : 1);
263	    // A single execution can be excused from the LE count by its own step. Two
264	    // or more cannot: we only know how the LAST one ended.
265	    const excused = runs === 1 && (j.step === STEP_PREFLIGHT_FAILED || j.step === STEP_SANDBOX);
266	    const prev = map.get(j.domain);
267	    map.set(j.domain, {
268	      total: (prev?.total ?? 0) + runs,
269	      leRelevant: (prev?.leRelevant ?? 0) + (excused ? 0 : runs),
270	      lastAt: prev && prev.lastAt > j.createdAt ? prev.lastAt : j.createdAt,
271	    });
272	  }
273	  return map;
274	}
