276	// ---------------------------------------------------------------------------
277	// "SSL enabled for this website" — the claim worker/websites.ts makes
278	// ---------------------------------------------------------------------------
279	
280	/**
281	 * Everything `websiteSslVerdict` is allowed to reason from. Structurally
282	 * compatible with `TlsProbe` in lib/http-probe.ts (kept as a separate shape so
283	 * this module stays free of ssh2 and remains importable by a test).
284	 */
285	export type WebsiteSslFacts = {
286	  /** `classifyCertbotOutcome(...).kind` for the `certbot --nginx` run. */
287	  certbot: CertbotOutcome["kind"];
288	  /** HTTP status from https://<domain>/ probed WITHOUT -k. "000" = no answer. */
289	  httpsCode: string;
290	  /** curl's exit code for that request. 60/51/91 = the chain was not trusted. */
291	  httpsRc: number;
292	  /** HTTP status from http://<domain>/ with redirects NOT followed. */
293	  httpCode: string;
294	  /** Where the plain-HTTP request would have gone ("" = nowhere). */
295	  redirectTo: string;
296	  /** `systemctl is-active nginx` after certbot rewrote the config. */
297	  nginxState: string;
298	  /** Did the probe script finish? */
299	  complete: boolean;
300	};
301	
302	export type WebsiteSslVerdict =
303	  | { ok: true; note: string; redirects: boolean }
304	  | { ok: false; reason: string };
305	
306	/**
307	 * Decide what `certbot --nginx` plus a read-back are allowed to tell the
308	 * customer about HTTPS on their site.
309	 *
310	 * INCIDENT: `websiteSsl` in worker/websites.ts accepted
311	 *
312	 *     run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i
313	 *
314	 * as proof, wrote `ssl: true`, and sent *"A Let's Encrypt certificate is
315	 * installed and HTTP redirects to HTTPS."* That is the SAME alternation M7 #6
316	 * removed from `classifyCertbotOutcome` — "not yet due for renewal" is what
317	 * certbot prints when it does NOTHING — and it had grown a second head:
318	 * `/Successfully/i` matches almost any certbot chatter. Nothing was ever read
319	 * back, so the message was sent for a site whose nginx certbot had just broken,
320	 * whose 443 nothing was listening on, and whose HTTP did not redirect anywhere.
321	 *
322	 * Ordered by what the customer loses, hardest first:
323	 *  1. nginx down  — EVERY site on that VM is dark, not just this one.
324	 *  2. TLS untrusted or absent — every visitor gets a full-page browser warning.
325	 *  3. certbot failed outright.
326	 * The redirect is reported, never assumed: `--redirect` is requested, but a
327	 * pre-existing `location /` can beat certbot's rewrite, and claiming a redirect
328	 * that is not there sends customers hunting for a mixed-content bug they do not
329	 * have.
330	 */
331	export function websiteSslVerdict(domain: string, f: WebsiteSslFacts): WebsiteSslVerdict {
332	  if (f.certbot === "failed") {
333	    return {
334	      ok: false,
335	      reason:
336	        `certbot did not obtain or install a certificate for ${domain}, so HTTPS is NOT enabled and nothing ` +
337	        `about your site changed. The usual causes are that ${domain} does not yet point at this server in ` +
338	        `DNS, or that port 80 is not reachable from the internet for the HTTP-01 challenge.`,
339	    };
340	  }
341	
342	  if (!f.complete) {
343	    return {
344	      ok: false,
345	      reason:
346	        `certbot ran for ${domain} but the verification step did not complete, so we cannot confirm HTTPS ` +
347	        `works and are not claiming that it does. Check the site in a browser and re-run this if it is fine.`,
348	    };
349	  }
350	
351	  // 1. certbot --nginx REWRITES nginx.conf and the vhost. If the daemon did not
352	  //    survive that, every site on this VM is down — say so before anything else.
353	  if (f.nginxState !== "active") {
354	    return {
355	      ok: false,
356	      reason:
357	        `certbot rewrote your nginx configuration for ${domain} and nginx is now "${f.nginxState}" — so NO ` +
358	        `site on this server is being served, not just this one. Diagnose immediately with: nginx -t ; ` +
359	        `systemctl status nginx ; journalctl -u nginx -n 50`,
360	    };
361	  }
362	
363	  // 2. Trust. The probe deliberately does not pass -k, so this is what a browser
364	  //    would do. An exit code from certbot cannot substitute for it.
365	  if (CERT_UNTRUSTED_RCS.includes(f.httpsRc)) {
366	    return {
367	      ok: false,
368	      reason:
369	        `https://${domain} is answering, but the certificate it serves is not trusted (curl error ${f.httpsRc}), ` +
370	        `so every visitor still gets a full-page security warning. HTTPS is not enabled. Check that nginx is ` +
371	        `serving fullchain.pem rather than cert.pem.`,
372	    };
373	  }
374	  if (f.httpsCode === "000") {
375	    return {
376	      ok: false,
377	      reason:
378	        `nothing answered on https://${domain} after certbot ran (curl exit ${f.httpsRc}), so HTTPS is NOT ` +
379	        `enabled — the certificate may exist without nginx listening on 443. Check: ss -ltnp | grep :443 ; ` +
380	        `nginx -T | grep -A5 "server_name ${domain}"`,
381	    };
382	  }
383	
384	  // A 5xx over TLS means the app is broken, but TLS itself demonstrably works —
385	  // that is a different problem from the one this job is about, so it is
386	  // reported rather than used to deny the certificate.
387	  const appNote =
388	    /^5\d\d$/.test(f.httpsCode)
389	      ? ` Note: https://${domain} currently returns HTTP ${f.httpsCode}, so your site itself is erroring — ` +
390	        `that is an application problem, not a certificate one.`
391	      : "";
392	
393	  const redirects = /^30[1278]$/.test(f.httpCode) && /^https:\/\//i.test(f.redirectTo);
394	  const redirectNote = redirects
395	    ? `Plain http:// requests redirect to https:// (HTTP ${f.httpCode}).`
396	    : `Plain http:// requests do NOT redirect to https:// yet (http:// answered ${f.httpCode}` +
397	      `${f.redirectTo ? ` → ${f.redirectTo}` : ""}), so visitors can still reach the insecure version.`;
398	
399	  const gotCert =
400	    f.certbot === "issued"
401	      ? `A Let's Encrypt certificate was issued and installed for ${domain}.`
402	      : `certbot reported the existing certificate for ${domain} is not yet due for renewal, so it reused ` +
403	        `that one rather than requesting a new one — nothing was re-issued.`;
404	
405	  return {
406	    ok: true,
407	    redirects,
408	    note:
409	      `${gotCert} We then fetched https://${domain} from the server with certificate verification ON: it ` +
410	      `answered HTTP ${f.httpsCode} over a trusted chain, and nginx is active. ${redirectNote}${appNote}`,
411	  };
412	}
413	
414	/** curl exit codes meaning "the peer certificate could not be verified". */
415	const CERT_UNTRUSTED_RCS = [60, 51, 91];
416	
417	/**
418	 * The sentence for a renewal that renewed nothing.
419	 *
420	 * Split out and tested because getting it wrong is the whole defect: the old
421	 * message said "renewed … valid until <the same date as before>", which reads as
422	 * a successful renewal and is exactly why nobody noticed.
423	 */
424	export function unchangedRenewalNote(domain: string, expiresAt: Date, isRenewal: boolean): string {
425	  const when = expiresAt.toISOString().slice(0, 10);
426	  return isRenewal
427	    ? `certbot did not issue a new certificate for ${domain} — it reported the existing one is not yet due ` +
428	        `for renewal and left it in place, valid until ${when}. Nothing changed. If you believe it IS due, ` +
429	        `the certificate on disk disagrees with our record and support should force a renewal.`
430	    : `A certificate for ${domain} already existed and certbot reused it rather than requesting a new one. ` +
431	        `It is valid until ${when}.`;
432	}
