function isBlockedIpv4(ip){const o=ipv4Octets(ip);if(!o)return false;const[a,b]=o;if(a===0)return true;if(a===127)return true;if(a===10)return true;if(a===172&&b>=16&&b<=31)return true;if(a===192&&b===168)return true;if(a===169&&b===254)return true;if(a===100&&b>=64&&b<=127)return true;if(a===192&&b===0&&o[2]===0)return true;if(a===192&&b===0&&o[2]===2)return true;if(a>=224)return true;return false;}
function isBlockedIpv6(ip){let addr=ip.toLowerCase();const pct=addr.indexOf("%");if(pct!==-1)addr=addr.slice(0,pct);const mapped=addr.match(/:((?:\d{1,3}\.){3}\d{1,3})$/);if(mapped)return isBlockedIpv4(mapped[1]);if(addr==="::1"||addr==="::")return true;const head=addr.split(":")[0]??"";const h=parseInt(head||"0",16);if(Number.isNaN(h))return true;if((h&0xfe00)===0xfc00)return true;if((h&0xffc0)===0xfe80)return true;return false;}
function isBlockedIp(ip){const k=net.isIP(ip);if(k===4)return isBlockedIpv4(ip);if(k===6)return isBlockedIpv6(ip);return true;}

